import{G as e,W as t,n,rt as r}from"./chunks/framework.BR9-gX-M.js";var i=JSON.parse(`{"title":"模拟电子技术基础（清华大学电子学教研组编）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/electrical/模拟电子技术基础.md","filePath":"docs/electrical/模拟电子技术基础.md"}`),a={name:`docs/electrical/模拟电子技术基础.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="模拟电子技术基础-清华大学电子学教研组编" tabindex="-1">模拟电子技术基础（清华大学电子学教研组编） <a class="header-anchor" href="#模拟电子技术基础-清华大学电子学教研组编" aria-label="Permalink to “模拟电子技术基础（清华大学电子学教研组编）”">​</a></h1><h2 id="绪论" tabindex="-1">绪论 <a class="header-anchor" href="#绪论" aria-label="Permalink to “绪论”">​</a></h2><h3 id="电信号" tabindex="-1">电信号 <a class="header-anchor" href="#电信号" aria-label="Permalink to “电信号”">​</a></h3><h4 id="什么是电信号" tabindex="-1">什么是电信号 <a class="header-anchor" href="#什么是电信号" aria-label="Permalink to “什么是电信号”">​</a></h4><p>信号是反映消息的物理量，消息需要借助于某些物理量（如声、光、电）的变化来表示和传递，在电子电路中的信号均为电信号。</p><h4 id="模拟信号和数字信号" tabindex="-1">模拟信号和数字信号 <a class="header-anchor" href="#模拟信号和数字信号" aria-label="Permalink to “模拟信号和数字信号”">​</a></h4><p>信号的形式是多种多样的，在电子电路中则将信号分为模拟信号和数字信号。模拟信号在时间和数值上具有连续性，数字信号在时间和数值上具有离散性。</p><h3 id="电子信息系统" tabindex="-1">电子信息系统 <a class="header-anchor" href="#电子信息系统" aria-label="Permalink to “电子信息系统”">​</a></h3><h4 id="模拟电子系统的组成" tabindex="-1">模拟电子系统的组成 <a class="header-anchor" href="#模拟电子系统的组成" aria-label="Permalink to “模拟电子系统的组成”">​</a></h4><p>无数字系统参与</p><ol><li>提取：从各种能产生电信号的设备中采集信号</li><li>预处理：利用隔离、滤波、阻抗变换等技术将信号分离并放大</li><li>加工：对信号采用运算、转换、比较、采样保持等不同的加工</li><li>驱动与执行：驱动执行机构</li></ol><p>有数字系统参与（常用）</p><ol><li>提取：从各种能产生电信号的设备中采集信号</li><li>预处理：利用隔离、滤波、阻抗变换等技术将信号分离并放大</li><li>加工：对信号采用运算、转换、比较、采样保持等不同的加工</li><li>A/D转换：将模拟信号转换为数字信号</li><li>数字系统：对数字信号进行处理</li><li>D/A转换：将处理后的数字信号转换为模拟信号</li><li>驱动与执行：驱动执行机构</li></ol><h4 id="电子信息系统的组成原则" tabindex="-1">电子信息系统的组成原则 <a class="header-anchor" href="#电子信息系统的组成原则" aria-label="Permalink to “电子信息系统的组成原则”">​</a></h4><ol><li>必须满足功能和性能指标要求</li><li>电路要尽量简单，集成电路能实现的不选用分立元件电路，大规模集成电路能实现的不选用小规模集成电路</li><li>电磁兼容性，在预定环境下能够抵御周围电磁场的干扰且较少的影响周围环境</li><li>可测性，合理引出测试点，设计自检电路</li></ol><h4 id="电子信息系统中的常用的模拟电路" tabindex="-1">电子信息系统中的常用的模拟电路 <a class="header-anchor" href="#电子信息系统中的常用的模拟电路" aria-label="Permalink to “电子信息系统中的常用的模拟电路”">​</a></h4><ol><li>放大电路：用于信号的电压、电流或功率放大</li><li>滤波电路：用于信号的提取、变换或抗干扰</li><li>运算电路：对信号进行运算</li><li>信号转换电路：不同形式的信号的转换，如电压信号和电流信号、直流信号和交流信号等</li><li>信号发生电路：用于产生正弦波、矩形波、三角波、锯齿波等不同信号</li><li>直流电源：将家用或工业交流电转换成直流电，作为电子电路的供电电源</li></ol>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};